insert into public.research_method (id, name, description, created_at, updated_at) values
  (1, 'Moderated usability test', 'A facilitator watches a participant attempt set tasks with a prototype or live product.', '2026-05-01T10:00:00+00:00', '2026-05-01T10:00:00+00:00'),
  (2, 'Contextual interview', 'An interview held where the participant normally does the activity.', '2026-05-01T10:00:00+00:00', '2026-05-01T10:00:00+00:00'),
  (3, 'Diary study', 'Participants log their own behaviour over several days or weeks.', '2026-05-01T10:00:00+00:00', '2026-05-01T10:00:00+00:00'),
  (4, 'Unmoderated survey', 'A short questionnaire completed without a facilitator.', '2026-05-01T10:00:00+00:00', '2026-05-01T10:00:00+00:00'),
  (5, 'Card sort', 'Participants group and label content cards to reveal their mental model.', '2026-05-01T10:00:00+00:00', '2026-05-01T10:00:00+00:00');
insert into public.research_project (id, title, description, research_objective, status, start_date, end_date, archived_at, created_at, updated_at) values
  (1, 'Mobile banking onboarding', 'Fictional demo project. Fernleaf, an imaginary retail bank, is redesigning account opening in its mobile app.', 'Understand where new customers abandon account opening and what would help them finish in one sitting.', 'active', '2026-08-03', null, null, '2026-08-01T10:00:00+00:00', '2026-08-01T10:00:00+00:00'),
  (2, 'Grocery checkout friction', 'Fictional demo project. Basketful, an imaginary grocery delivery app, sees many full baskets abandoned at checkout.', 'Identify the moments of friction between a full basket and a confirmed delivery slot.', 'active', '2026-08-24', null, null, '2026-08-20T10:00:00+00:00', '2026-08-20T10:00:00+00:00'),
  (3, 'Library catalogue search', 'Fictional demo project. An imaginary city library wants catalogue search to work for people who don''t know exact titles.', 'Learn how patrons look for books they only half remember, and what search should do with vague queries.', 'completed', '2026-06-01', '2026-07-31', null, '2026-05-28T10:00:00+00:00', '2026-05-28T10:00:00+00:00'),
  (4, 'Clinic appointment reminders', 'Fictional demo project, paused and archived after one scoping session.', 'Explore whether text reminders reduce missed appointments for an imaginary community clinic.', 'paused', '2026-05-04', null, null, '2026-05-02T10:00:00+00:00', '2026-05-02T10:00:00+00:00');
