insert into public.observation (id, session_id, title, description, sentiment, created_at, updated_at) values
  (1, 1, 'Stopped at the proof-of-address step', 'P-01 paused for about a minute at ''Upload proof of address'', said they had no utility bill on their phone, and closed the app to look for one.', 'negative', '2026-08-10T15:00:00+00:00', '2026-08-10T15:00:00+00:00'),
  (2, 1, 'Found the step counter reassuring', 'P-01 pointed at the step counter and said it helped to know there were only five steps.', 'positive', '2026-08-10T15:00:00+00:00', '2026-08-10T15:00:00+00:00'),
  (3, 2, 'Unsure which documents count', 'P-02 asked aloud whether a statement from another bank would be accepted. The screen did not say.', 'negative', '2026-08-11T15:00:00+00:00', '2026-08-11T15:00:00+00:00'),
  (4, 2, 'Hesitated at the camera permission', 'P-02 read the camera permission prompt twice and asked why the app needed it before tapping Allow.', 'negative', '2026-08-11T15:00:00+00:00', '2026-08-11T15:00:00+00:00'),
  (5, 3, 'Left the app to find a document', 'P-03 switched to their email to search for an electricity bill, then came back to find the form had reset.', 'negative', '2026-08-12T15:00:00+00:00', '2026-08-12T15:00:00+00:00'),
  (6, 3, 'Identity check was quick once started', 'P-03 finished the selfie check in under a minute and said it was easier than expected.', 'positive', '2026-08-12T15:00:00+00:00', '2026-08-12T15:00:00+00:00'),
  (7, 4, 'Expected a checklist before starting', 'P-04 said their previous bank emailed a list of what to prepare, and they wanted the same here.', 'neutral', '2026-08-14T15:00:00+00:00', '2026-08-14T15:00:00+00:00'),
  (8, 4, 'Enlarged text cut off button labels', 'P-04 uses enlarged system text. The Continue button label was truncated on two screens.', 'negative', '2026-08-14T15:00:00+00:00', '2026-08-14T15:00:00+00:00'),
  (9, 5, 'Delivery fee appeared only at payment', 'P-05 noticed the delivery fee on the payment screen and went back to the basket to remove items.', 'negative', '2026-08-31T15:00:00+00:00', '2026-08-31T15:00:00+00:00'),
  (10, 5, 'Slot grid was hard to scan', 'P-05 scrolled the delivery slot grid twice before finding an evening slot.', 'negative', '2026-08-31T15:00:00+00:00', '2026-08-31T15:00:00+00:00'),
  (11, 6, 'Minimum spend message came too late', 'P-06 saw the minimum spend message only after tapping Checkout.', 'negative', '2026-09-01T15:00:00+00:00', '2026-09-01T15:00:00+00:00'),
  (12, 6, 'Wanted to share slot options', 'P-11 wanted to send two slot options to their partner before committing.', 'neutral', '2026-09-01T15:00:00+00:00', '2026-09-01T15:00:00+00:00'),
  (13, 6, 'Saved card made payment fast', 'Both participants paid within seconds once a saved card was selected.', 'positive', '2026-09-01T15:00:00+00:00', '2026-09-01T15:00:00+00:00'),
  (14, 7, 'Slots chosen around work shifts', 'Diary entries from P-05 and P-11 show slots picked around shift patterns, often the same slot each week.', 'neutral', '2026-09-08T15:00:00+00:00', '2026-09-08T15:00:00+00:00'),
  (15, 7, 'Rebuilt the same basket every week', 'P-06 rebuilt a near-identical basket by hand each week.', 'neutral', '2026-09-08T15:00:00+00:00', '2026-09-08T15:00:00+00:00'),
  (16, 8, 'Left when the total beat expectations', 'P-08 closed the app after seeing the total with fees, saying it was more than the shelf price.', 'negative', '2026-09-10T15:00:00+00:00', '2026-09-10T15:00:00+00:00'),
  (17, 8, 'Screen reader skipped slot availability', 'P-07''s screen reader announced slot times but not whether each slot was available.', 'negative', '2026-09-10T15:00:00+00:00', '2026-09-10T15:00:00+00:00'),
  (18, 9, 'Searched by plot description', 'P-09 typed ''book about a lighthouse keeper''s daughter'' and got no results.', 'negative', '2026-06-10T15:00:00+00:00', '2026-06-10T15:00:00+00:00'),
  (19, 9, 'Would ask a librarian instead', 'After two failed searches P-09 said they would normally ask at the desk.', 'neutral', '2026-06-10T15:00:00+00:00', '2026-06-10T15:00:00+00:00'),
  (20, 10, 'Remembered the cover, not the title', 'P-10 remembered a green cover with a bird on it, but not the title or author.', 'neutral', '2026-06-12T15:00:00+00:00', '2026-06-12T15:00:00+00:00'),
  (21, 10, 'Misspelled author returned nothing', 'P-10 misspelled the author''s surname and the catalogue returned no results and no suggestion.', 'negative', '2026-06-12T15:00:00+00:00', '2026-06-12T15:00:00+00:00'),
  (22, 11, 'Grouped results by subject', 'Most participants grouped result cards by what the book is about rather than by format.', 'neutral', '2026-06-24T15:00:00+00:00', '2026-06-24T15:00:00+00:00'),
  (23, 11, 'Put available titles first', 'Participants moved ''Available now'' cards to the top of every group.', 'neutral', '2026-06-24T15:00:00+00:00', '2026-06-24T15:00:00+00:00'),
  (24, 12, 'Reads texts, ignores app alerts', 'P-12 said they ignore app notifications but always read text messages.', 'neutral', '2026-05-20T15:00:00+00:00', '2026-05-20T15:00:00+00:00');
insert into public.finding (id, project_id, title, confidence, created_at, description, updated_at) values
  (1, 1, 'Proof of address is the main drop-off point', 'high', '2026-08-17T10:00:00+00:00', 'Three of four participants stopped at the proof-of-address step because they had no suitable document on their phone.', '2026-08-17T10:00:00+00:00'),
  (2, 1, 'People don''t know what to prepare', 'medium', '2026-08-17T10:00:00+00:00', 'Participants started without knowing which documents would be accepted and expected guidance before step one.', '2026-08-17T10:00:00+00:00'),
  (3, 1, 'The camera request needs a reason', 'medium', '2026-08-17T10:00:00+00:00', 'The system camera prompt appeared without explanation, causing hesitation, although the check itself went smoothly.', '2026-08-17T10:00:00+00:00'),
  (4, 1, 'Progress is lost when people leave the app', 'high', '2026-08-17T10:00:00+00:00', 'Leaving the app to find a document reset the form, forcing participants to start again.', '2026-08-17T10:00:00+00:00'),
  (5, 1, 'Enlarged text breaks key buttons', 'medium', '2026-08-18T10:00:00+00:00', 'With enlarged system text, primary button labels were truncated on two onboarding screens.', '2026-08-18T10:00:00+00:00'),
  (6, 2, 'Costs appear too late', 'high', '2026-09-12T10:00:00+00:00', 'Delivery fees and the minimum spend surfaced after the basket, prompting edits or abandonment.', '2026-09-12T10:00:00+00:00'),
  (7, 2, 'Slot selection is slow to scan', 'medium', '2026-09-12T10:00:00+00:00', 'Finding a suitable slot took repeated scrolling, and availability was not announced to screen readers.', '2026-09-12T10:00:00+00:00'),
  (8, 2, 'Shoppers repeat the same order', 'medium', '2026-09-12T10:00:00+00:00', 'Weekly shoppers recreate similar baskets and pick the same slot each week.', '2026-09-12T10:00:00+00:00'),
  (9, 3, 'Patrons search with memory cues, not metadata', 'high', '2026-06-26T10:00:00+00:00', 'Patrons describe plots or covers instead of titles and authors, which the catalogue cannot match.', '2026-06-26T10:00:00+00:00'),
  (10, 3, 'Zero results is a dead end', 'high', '2026-06-26T10:00:00+00:00', 'Searches with no results offered no suggestions, so patrons gave up or planned to ask staff.', '2026-06-26T10:00:00+00:00'),
  (11, 3, 'Availability matters more than format', 'medium', '2026-06-26T10:00:00+00:00', 'In the card sort, participants prioritised whether a book was available over its format.', '2026-06-26T10:00:00+00:00');
insert into public.insight (id, project_id, title, impact, created_at, description, updated_at) values
  (1, 1, 'New customers start without the documents they need', 'high', '2026-08-20T10:00:00+00:00', 'Account opening assumes people arrive prepared. Most don''t, so the first real task is finding paperwork.', '2026-08-20T10:00:00+00:00'),
  (2, 1, 'Leaving the app is part of the journey', 'high', '2026-08-20T10:00:00+00:00', 'Going to find a document is expected behaviour, so progress has to survive people leaving and returning.', '2026-08-20T10:00:00+00:00'),
  (3, 1, 'Trust comes before the camera', 'medium', '2026-08-20T10:00:00+00:00', 'People accept identity checks once they understand why the camera is needed.', '2026-08-20T10:00:00+00:00'),
  (4, 2, 'Shoppers judge the basket by its final price', 'high', '2026-09-15T10:00:00+00:00', 'The number that matters is the total including fees; anything hidden until payment feels like a surprise charge.', '2026-09-15T10:00:00+00:00'),
  (5, 2, 'Delivery slots are a routine, not a fresh choice', 'medium', '2026-09-15T10:00:00+00:00', 'Most weekly shoppers want the same slot as last time, so a full grid is overhead.', '2026-09-15T10:00:00+00:00'),
  (6, 3, 'Search needs to forgive vague and misspelled queries', 'high', '2026-06-29T10:00:00+00:00', 'Exact-match search fails the way people actually remember books.', '2026-06-29T10:00:00+00:00'),
  (7, 3, 'Availability is the first filter patrons apply', 'medium', '2026-06-29T10:00:00+00:00', 'Patrons decide what to borrow based on what they can get today.', '2026-06-29T10:00:00+00:00');
insert into public.recommendation (id, project_id, title, priority, status, created_at, description, updated_at) values
  (1, 1, 'Show a ''what you''ll need'' checklist before step one', 'high', 'accepted', '2026-08-24T10:00:00+00:00', 'List accepted documents and examples on a preparation screen before the form begins.', '2026-08-24T10:00:00+00:00'),
  (2, 1, 'Save progress automatically and resume where people left off', 'high', 'accepted', '2026-08-24T10:00:00+00:00', 'Store a draft after each step so returning to the app restores the form.', '2026-08-24T10:00:00+00:00'),
  (3, 1, 'Explain the camera before the system prompt', 'medium', 'accepted', '2026-08-24T10:00:00+00:00', 'Show a short explanation of the identity check before triggering the operating system permission.', '2026-08-24T10:00:00+00:00'),
  (4, 1, 'Accept a wider range of address documents', 'medium', 'proposed', '2026-08-25T10:00:00+00:00', 'Allow statements from other banks and digital letters as proof of address.', '2026-08-25T10:00:00+00:00'),
  (5, 2, 'Show fees and minimum spend in the basket', 'high', 'accepted', '2026-09-17T10:00:00+00:00', 'Display the delivery fee, minimum spend and running total in the basket, not only at payment.', '2026-09-17T10:00:00+00:00'),
  (6, 2, 'Offer ''same slot as last week'' first', 'medium', 'proposed', '2026-09-17T10:00:00+00:00', 'Put the shopper''s previous slot at the top of slot selection when it is available.', '2026-09-17T10:00:00+00:00'),
  (7, 3, 'Add spelling suggestions and description search', 'high', 'accepted', '2026-07-02T10:00:00+00:00', 'Suggest corrected spellings and match words in summaries and subjects, not only titles and authors.', '2026-07-02T10:00:00+00:00'),
  (8, 3, 'Make ''available now'' the default sort', 'medium', 'rejected', '2026-07-02T10:00:00+00:00', 'Sort results so books on the shelf appear first.', '2026-07-02T10:00:00+00:00');
insert into public.design_decision (id, project_id, title, status, decided_on, created_at, description, updated_at) values
  (1, 1, 'Add a preparation screen to account opening', 'implemented', '2026-09-02', '2026-09-02T10:00:00+00:00', 'A preparation screen listing accepted documents now opens the flow, so people gather paperwork before starting.', '2026-09-02T10:00:00+00:00'),
  (2, 1, 'Keep onboarding drafts for seven days', 'approved', '2026-09-04', '2026-09-04T10:00:00+00:00', 'Drafts persist for seven days so people can leave to find documents without losing progress.', '2026-09-04T10:00:00+00:00'),
  (3, 1, 'Add a pre-permission screen for camera access', 'implemented', '2026-09-02', '2026-09-02T10:00:00+00:00', 'A screen explaining the identity check appears before the system camera prompt.', '2026-09-02T10:00:00+00:00'),
  (4, 2, 'Move the fee summary into the basket', 'approved', '2026-09-18', '2026-09-18T10:00:00+00:00', 'Fees and minimum spend move into the basket so the final total is visible before checkout.', '2026-09-18T10:00:00+00:00'),
  (5, 2, 'Pilot a ''repeat last slot'' shortcut', 'proposed', null, '2026-09-22T10:00:00+00:00', 'Test a one-tap option to rebook the previous slot with a small group of weekly shoppers.', '2026-09-22T10:00:00+00:00'),
  (6, 3, 'Use fuzzy matching in catalogue search', 'implemented', '2026-07-28', '2026-07-28T10:00:00+00:00', 'Search tolerates misspellings and matches summary text, so vague queries return candidates.', '2026-07-28T10:00:00+00:00');
